-- C-103 : mise à niveau des relevés IPES déjà installés (DOC-09 relevé semestriel, DOC-10 relevé annuel et cumulatif). Les établissements qui ont
-- installé le catalogue avant DOC-BUL gardent l'ancien modèle à emplacements u01 à u10 (limite de 10 UE). Cette migration, idempotente, déclare au type
-- les variables du nouveau modèle (tableau units_table ou annual_table, rang) puis ajoute une NOUVELLE version validée du modèle FR et EN : l'ancienne
-- version reste en base pour les documents déjà émis. Seuls sont concernés les modèles dont la dernière version n'utilise pas encore un tableau du moteur
-- (un modèle déjà à jour ou déjà personnalisé avec un tableau n'est jamais touché). Le HTML est celui du catalogue (HigherDocumentCatalog::html), sans point-virgule.
-- Identifiants des nouvelles lignes : 01C103T suivi de la fin de l'identifiant de la version reprise.

UPDATE document_types SET variables = REPLACE(variables, ']', ',"units_table","rank_info"]'), updated_at = '2026-11-05T12:01:00+01:00' WHERE code = 'hi_doc09' AND tenant_id <> '*' AND variables NOT LIKE '%"units_table"%';
UPDATE document_types SET variables = REPLACE(variables, ']', ',"annual_table","rank_info"]'), updated_at = '2026-11-05T12:01:00+01:00' WHERE code = 'hi_doc10' AND tenant_id <> '*' AND variables NOT LIKE '%"annual_table"%';

INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) SELECT REPLACE(t.id, SUBSTR(t.id, 1, 7), '01C103T'), t.tenant_id, t.establishment_id, t.type_code, t.locale, '<html><body><style>header{border-bottom:3px solid {{school_color}}}header{padding-bottom:6px}header h2{color:{{school_color}}}</style><header><img src="{{school_logo_url}}" alt="" height="60"><h1>{{establishment_name}}</h1><h2>{{school_name}}</h2><p>{{school_header}}</p></header><h2>{{document_title}}</h2><style>@page{margin:1cm 1.2cm}body{font-size:9.5px}body{line-height:1.3}header h1{font-size:15px}header h1{margin:2px 0}header h2{font-size:12px}header h2{margin:2px 0}header img{float:left}header p{margin:2px 0}header p{font-size:8.5px}h2{font-size:13px}h2{margin:6px 0 4px 0}.authority{text-align:center}.authority{font-size:8.5px}.authority{margin:2px 0}.identity,.synthesis{width:100%}.identity,.synthesis{border-collapse:collapse}.identity,.synthesis{margin:4px 0}.identity td{padding:1px 4px}.identity td{border:1px solid #999}.synthesis td{padding:3px 4px}.synthesis td{border:1px solid #555}.doc-table{font-size:8.5px}.doc-table th{font-size:8px}.doc-row-group td{background:#eef2f7}.note{font-size:8px}.note{font-style:italic}</style><div align="center">{{logo}}</div><p class="authority">Autorisation n° {{authorization_ref}} · Université de tutelle : {{tutelage_name}}</p><table class="identity"><tr><td>Nom / <i>Surname</i> : <strong>{{holder_last_name}}</strong></td><td>Prénoms / <i>Given names</i> : <strong>{{holder_first_names}}</strong></td></tr><tr><td>Né(e) le / <i>Date of birth</i> : {{birth_info}}</td><td>Matricule / <i>Registration no.</i> : <strong>{{holder_matricule}}</strong></td></tr><tr><td>Filière / <i>Programme</i> : {{program_name}}</td><td>Niveau / <i>Level</i> : {{level_name}}</td></tr><tr><td>Période / <i>Period</i> : {{semester_label}} ({{session_label}})</td><td>Année académique / <i>Academic year</i> : {{academic_year}}</td></tr></table><div class="units">{{table:units_table}}</div><table class="synthesis"><tr><td>Moyenne / <i>Average</i> : <strong>{{semester_average}}</strong>/20</td><td>MGP / <i>GPA</i> : <strong>{{gpa}}</strong>/4</td><td>Crédits capitalisés / <i>Credits earned</i> : <strong>{{credits_earned}}</strong>/{{credits_total}}</td><td>Rang / <i>Rank</i> : {{rank_info}}</td></tr><tr><td colspan="3">Décision du jury / <i>Board decision</i> : <strong>{{decision}}</strong></td><td>Mention / <i>Honours</i> : {{mention}}</td></tr></table><p class="note">Délibération réf. {{jury_ref}}</p><p>Fait à {{issue_place}}, le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div class="qr">{{qr}}</div><p><small>Seul l''original signé ou vérifié en ligne fait foi : {{verification_url}}</small></p></body></html>', t.version + 1, '2026-11-05T12:01:00+01:00', NULL, '2026-11-05T12:01:00+01:00' FROM document_templates t WHERE t.tenant_id <> '*' AND t.type_code = 'hi_doc09' AND t.locale = 'fr' AND t.html NOT LIKE '%{{table:%' AND t.version = (SELECT MAX(m.version) FROM document_templates m WHERE m.tenant_id = t.tenant_id AND m.establishment_id = t.establishment_id AND m.type_code = t.type_code AND m.locale = t.locale);
